export type TriggerType =
  | 'task_complete'
  | 'quest_complete'
  | 'hard_task_complete'
  | 'level_up'
  | 'rank_up'
  | 'streak_milestone'
  | 'task_skipped'
  | 'task_missed'
  | 'xp_loss'
  | 'rank_in_danger'
  | 'comeback'
  | 'morning_start'
  | 'task_reminder'
  | 'idle_motivation'
  | 'focus_start'
  | 'focus_end'
  | 'night_review'
  | 'character_select'
  | 'attack_line';

export type LineRarity = 'normal' | 'hype' | 'legendary';
export type CharacterExpression = 'happy' | 'proud' | 'serious' | 'angry' | 'surprised';

export interface VoiceLine {
  text: string;
  rarity: LineRarity;
  timeOfDay?: 'morning' | 'afternoon' | 'night';
  expression: CharacterExpression;
  customAudioKey?: string;
}

export interface CharacterVoiceSettings {
  preferredVoiceName?: string;
  pitch: number;
  rate: number;
  volume: number;
  fallbackLang: string;
}

export interface CharacterVoiceProfile {
  id: 'goku' | 'naruto' | 'asta' | 'saitama' | 'madara';
  displayName: string;
  avatarImage: string;
  themeColor: string;
  personalityDescription: string;
  voiceSettings: CharacterVoiceSettings;
  customAudio: Record<string, string>;
  lines: Record<TriggerType, VoiceLine[]>;
}

